//! The statistics' critical-value tables (src/stats/tables.rs, generated by
//! scripts/gen_stat_tables.py from statsmodels) are pinned by digest, and cross-checked against
//! the distribution functions they approximate.

use raptorbt::journal::sha256_hex;
use raptorbt::math::special::chi2_sf;
use raptorbt::stats::tables;

/// The digest `scripts/gen_stat_tables.py` prints. A changed table is a changed digest: rerun the
/// script, read the diff of tables.rs, and update this line in the same commit.
const DIGEST: &str = "4995d1a2055e77e7529b8484024e4e7d58c80862d997f7a61b51fa7a1035ab7f";

#[test]
fn constants_digest_is_pinned() {
    // "name\n" then the 16 hex digits of each value's IEEE bits and "\n": the text the
    // generator hashes
    let mut text = String::new();
    for (name, values) in tables::constants() {
        text.push_str(name);
        text.push('\n');
        for v in values {
            text.push_str(&format!("{:016x}\n", v.to_bits()));
        }
    }
    assert_eq!(sha256_hex(text.as_bytes()), DIGEST, "src/stats/tables.rs changed: see DIGEST");
}

/// The extents the known `mackinnonp` defect depends on: the 1994 p-value tables stop at six
/// series, the 2010 critical values answer for twelve.
#[test]
fn mackinnon_1994_stops_at_six_and_2010_reaches_twelve() {
    assert_eq!(tables::MACKINNON_1994_MAX_N, 6);
    assert_eq!(tables::MACKINNON_2010_MAX_N, 12);
    for reg in 0..4 {
        assert_eq!(tables::TAU_MAX[reg].len(), 6);
        assert_eq!(tables::TAU_MIN[reg].len(), 6);
        assert_eq!(tables::TAU_STAR[reg].len(), 6);
        assert_eq!(tables::TAU_SMALLP[reg].len(), 6);
        assert_eq!(tables::TAU_LARGEP[reg].len(), 6);
    }
    assert_eq!(tables::TAU_2010_C.len(), 12);
    assert_eq!(tables::TAU_2010_CT.len(), 12);
    assert_eq!(tables::TAU_2010_CTT.len(), 12);
    // the no-constant surface has N = 1 only
    assert_eq!(tables::TAU_2010_N.len(), 1);
    assert_eq!(tables::JOHANSEN_TRACE[0].len(), 12);
    assert_eq!(tables::JOHANSEN_MAX_EIG[2].len(), 12);
}

/// The asymptotic 1%, 5% and 10% ADF critical values with a constant (MacKinnon 2010), and the
/// KPSS critical values (Kwiatkowski et al. 1992, Table 1).
#[test]
fn asymptotic_critical_values_are_the_published_ones() {
    assert_eq!(tables::TAU_2010_C[0][0][0], -3.43035);
    assert_eq!(tables::TAU_2010_C[0][1][0], -2.86154);
    assert_eq!(tables::TAU_2010_C[0][2][0], -2.56677);
    assert_eq!(tables::TAU_2010_N[0][1][0], -1.941);
    assert_eq!(tables::KPSS_CRIT_C, [0.347, 0.463, 0.574, 0.739]);
    assert_eq!(tables::KPSS_CRIT_CT, [0.119, 0.146, 0.176, 0.216]);
    assert_eq!(tables::KPSS_PVALS, [0.10, 0.05, 0.025, 0.01]);
}

/// With one series the Johansen trace and maximum-eigenvalue statistics are the same
/// distribution, and with a constant restricted to the cointegrating relation it is a
/// chi-squared with one degree of freedom (det_order 0 here is MacKinnon-Haug-Michelis' case 2,
/// whose n = 1 row is the chi-squared(1) quantile). The chi-squared tail comes from
/// `math::special`, not from the table's source, so this ties the two together.
#[test]
fn johansen_one_series_row_is_the_chi_squared_quantile() {
    for det in 0..3 {
        assert_eq!(tables::JOHANSEN_TRACE[det][0], tables::JOHANSEN_MAX_EIG[det][0]);
    }
    // det_order 0 (index 1): 90%, 95%, 99% points of a chi-squared with one degree of freedom
    let row = tables::JOHANSEN_TRACE[1][0];
    for (value, level) in row.iter().zip([0.10, 0.05, 0.01]) {
        let tail = chi2_sf(*value, 1.0).unwrap();
        assert!((tail - level).abs() < 5e-5, "chi2_sf({value}, 1) = {tail}, expected {level}");
    }
}

/// Rows of the Johansen tables grow with n and with the confidence level.
#[test]
fn johansen_rows_increase() {
    for table in [&tables::JOHANSEN_TRACE, &tables::JOHANSEN_MAX_EIG] {
        for det in table.iter() {
            for n in 0..12 {
                assert!(det[n][0] < det[n][1] && det[n][1] < det[n][2]);
                if n > 0 {
                    assert!(det[n][1] > det[n - 1][1]);
                }
            }
        }
    }
}
